          "TikTok创作者奖励规则说明资格取决于实际账号、地区与内容。合格播放来自符合条件的 For You 信息流，并排除部分播放来源和行为。视频在加入后发布且应符合原创、片长等要求，广告、付费推广和赞助不在合格类别内。旧基金数据不能替代当前项目资格。若品牌需要理解如何分开算，使用活动衡量与对账指南。报告时写清公开播放、合格播放与估算金额分别在哪里看到。当前看到规则不代表某个人已经加入。",
          "TikTok Creator Rewards requirements describe eligibility at account, market and content levels. Qualified views use an eligible For You scope and exclude certain sources and viewing events. The video needs to meet relevant originality and duration rules and be posted after admission. Ads, paid promotions and sponsored content are among the listed exclusions. A legacy Fund record cannot establish eligibility under the current program. Use the campaign measurement guide to separate platform results and brand deliverables. In reporting, identify the source for public views, qualified views and any estimated amount. Reading the published rule does not show that a creator has enrolled. Suppose a brand receives a current screenshot showing qualified views for one video. The screenshot may be useful for that account and post if the holder authorizes it. It does not establish earnings for unrelated videos or make sponsored content eligible. Have the account holder confirm the actual program status and leave unavailable details open. Check the current official rules at the time of each new campaign."
