          "用达人费率与使用权指南拆分制作、发布、修订、原片、广告、地域和期限。费用与交付状态挂钩时，写明审核人、期限和可验证条件。假设创作者独立制作长教程，另为品牌做短片，两个项目各有预算。平台奖励的变动不会自动改变已约定的制作费。若双方同意绩效奖金，就明确采用哪份活动报表与哪类可验证事件，不用其他作品的奖励数字填补。营销报告和创作者私人结算只共享项目确实需要的范围。",
          "Use the creator rates and usage rights guide to separate production, publication, revisions, raw footage, paid use, territory and term. When fees depend on delivery, name the reviewer, date and verifiable condition. Suppose the creator independently makes longer tutorials and produces a short demonstration for the brand. Give the two projects separate budgets. A change in platform rewards does not alter the agreed production fee by itself. If the parties choose a performance bonus, identify the exact campaign report and qualifying event. Do not use rewards from unrelated videos to fill missing data. Share only the scope the project needs. For example, a client can verify the public post and its agreed publication date without seeing the creator’s earnings history. If the brand later wants to run the edit as an ad, review the approved rights and payment terms before using it. Treat the commercial change as a decision about a specific asset, not a correction to platform income. Give finance the agreement, approved version and receipt of the deliverable so the invoice can be reviewed independently."
