          "Separate product questions, feedback, individual support, repetitive harassment, possible rule violations and urgent risks. If someone reports a late delivery, acknowledge the feedback and provide the official support route without requesting order numbers, home addresses or phone numbers in public. Route verifiable product criticism to the relevant product or editorial owner. A recurring question may deserve a public answer that can be shared again. Privacy or safety concerns need a different escalation owner. Use the Bluesky public conversation guide to keep the relevant context. A disappointed customer, a question asked in good faith and an abusive message call for different decisions even if all three appear under a launch post. Staff can document a short reason for the response class without labeling the person. Agree on how to handle sarcasm or unclear language. When the message is ambiguous, a private internal review can be more appropriate than either a public accusation or an automatic removal. If the same complaint reveals a real product issue, track the resolution separately from any platform action."
