          "The Bluesky Terms of Service distinguish Discover recommendations from third-party feeds. What one brand account sees depends on its feed and settings and does not represent every user’s view. The AT Protocol moderation documentation describes labels and subscriptions. The Bluesky Community Guidelines distinguish baseline platform rules from additional labeling services. Record which mute, block, reply and reporting controls are available in the actual account. For each control, note who can use it, which interactions it affects and how it can be reversed. A local visibility result does not establish that content disappeared from the service. Ask two authorized colleagues to review a harmless test post in their normal clients and compare the agreed evidence. If their feed settings differ, document the difference instead of inferring a platform-wide result. Consider whether a moderation setting is appropriate for the brand’s goal, such as reducing repeated interruptions to support staff. Keep a record of the setting version so the next person knows which configuration was in effect during a pilot. Review implications before adopting a third-party labeling service."
