          "The YouTube channel ID help explains that channels have distinct identifiers and that the primary owner can access the relevant IDs in settings. Record the public channel URL, a verified identifier where available, current name and observation date. The presenter, producer and business contact can be different people. Use the published contact route and confirm who can discuss posting and asset rights. If a different host or regional account will perform the assignment, review whether the selected work represents that delivery. A video attributed to a network might be published by a separate member channel. Keep the contract subject and actual publication account explicit. If a creator renamed a channel, preserve the date you observed the new name and verify the older links. An apparent match in display names should not be enough to send a confidential brief. Keep a record of who confirmed the intended contact and what they are authorized to approve. Record the information at the level your team actually needs."
