          "The YouTube channel ID help describes unique user and channel IDs and explains where the primary owner can find them. The YouTube handle help describes handles beginning with the at sign, distinct from channel names and subject to change. Record a verified channel ID, current handle, display name, public URL and observation date. Leave the ID pending when you cannot verify it. If an old record stores only a name, inspect the uploader on the relevant videos before joining records. Similar names and avatars do not establish a match. Preserve the former name and the evidence linking it to the current channel. A channel may update its public name without changing the assets already published. Another channel can publish under a very similar public label. Give a reviewer enough detail to distinguish both. If a report relies on a secondary database’s mapping, compare it with the actual video and record which source supplied the identifier. A contact route should still be confirmed separately before anyone shares an unpublished campaign brief."
