          "The YouTube playlist help defines a playlist as a collection of videos and describes how other people can add videos where appropriate. Inclusion does not establish that the list owner uploaded, licensed or sponsored each video. Open the work itself and record the uploader, video link, publication date and relevant timecode. Suppose a network’s playlist displays work by different creators. Keep it as the discovery route while recording each actual uploader as a separate fact. If the playlist groups sponsored videos, review the particular video and agreement before describing the commercial relationship. A video can appear in several collections without changing its uploader. If it has been reuploaded, distinguish the new upload from the earlier record and check which version the claim concerns. A campaign report should link to the contracted post. If a related channel uploads a promotional clip, track it separately. Otherwise an analyst may report the combined audience of items that were never part of the same commitment."
