          "频道主持人、制作公司、经纪和账号管理员可能不同。让联系人确认哪一方可接受制作条款、哪一方能发布、哪一方能同意品牌使用。用达人费率与使用权指南拆出原片、发布、衍生、广告和期限。若只买了某频道发帖，不能由频道关联关系推断品牌可以复制到其他账号。遇到共同制作时，对具体资产核对许可来源和适用范围。",
          "A host, production company, representative and channel manager can be different people. Ask who can agree to production terms, who can publish and who can grant the brand’s intended use. Use the creator rates and usage rights guide to separate raw footage, publication, derivatives, ads and term. Buying a post on one channel does not establish permission to copy it to related accounts. For a joint production, review the permission source and limits for the particular asset. In a hypothetical handoff, a host can confirm their availability while a production company controls footage and a separate agency manages the brand placement. Let the people responsible for those decisions confirm each item. If a regional version requires a new voiceover or different music, identify who will approve the change. The publisher may need an approved copy and asset even when they do not handle payment. Keep the commercial record and channel access separate so someone can review authority without getting more operational access than they need."
