          "The YouTube channel permissions help describes role-based access without sharing a Google account. Review current roles and what they can view, edit, publish or remove in the actual account. Ask the authorized administrator to run any necessary check with approved test content. Leave live scheduled items undisturbed. If an external agency only needs to review a specific asset, check the appropriate review route before considering broader channel access. Record account recovery ownership and access review at departure or expiry. Do not store passwords in the handoff. Suppose a collaborator can see approved footage in a shared project folder but cannot schedule a video. That may match the planned role. Confirm the designated publisher can use the correct channel at the promised time. If someone can view reports for several channels, check which one the saved report represents before sending it to a client. Verify permission with the actual work the person needs to do rather than inferring from a job title."
