          "The Shopify Collabs program setup guide describes open access and invite programs. Eligible creators may obtain links under open access. An invite program is for selected creators. The guide also describes market eligibility for open access. Check the actual store configuration, available program, products, regions, current rates and owners. If a brand needs to review product language before a creator publishes, examine the real process for the selected relationship. Use the campaign brief guide to document the product, window and separately agreed production or posting work. A small apparel store might test one collection with two creators before considering another product line. List which SKUs belong to the pilot and which purchases should be excluded under the actual program. Confirm which country and currency the customer will encounter. A store can have several offers that appear similar to a customer while using different commission rules. Store the version and start date so finance can reconcile orders placed before and after a program change."
