          "The Shopify Collabs merchant payment guide explains that creators can earn commission through tracked affiliate links or discount codes. For each test case, record the creator, program, link or code, product, order identifier, time, currency and report source. A link click and code use at checkout are distinct events. Verify commission from the actual order record. If one order has evidence of both routes, do not count it twice. Put a deduplication rule and an unknown classification in the reporting notes. Suppose a buyer first opens a link on a phone and later uses a code on a desktop. The brand should not invent a cross-device attribution sequence from a final order row. Check what each system actually associates with that transaction. If a code appears in two places, preserve the intended creator and actual platform attribution while investigating any mismatch. A customer’s billing information is not required for a broad campaign recap. Give reviewers the necessary order reference and restrict the detailed record to authorized staff."
