          "Shopify Collabs 商家付款帮助称默认保留期 30 天，商家可按设置调整，保留期间取消或全额退款的订单会取消佣金。部分退款、跨保留期变动或改价要查看实际记录，不套用全退结论。保存订单、退款时间、金额与状态。假设符合条件的销售额为 100 美元、佣金率 10%，初始预估是 10 美元；保留期内全退后按平台记录更新为已取消。不要用当前商品价格覆盖交易当天数据。",
          "The Shopify Collabs merchant payment guide describes a default thirty-day holding period that merchants can configure. Canceled and fully refunded orders have commissions canceled during that period under the documented process. For a partial refund, later change or price adjustment, inspect actual records rather than applying the full-refund result. Preserve order reference, refund time, amount and observed status. Suppose the eligible sales amount is 100 dollars and the applicable rate is ten percent. The initial commission estimate is ten dollars. If the order receives a full refund during the hold, record the resulting canceled status from the platform. Do not replace the original transaction value with today’s price. A store analyst can keep the order row and cancellation row linked so a later export can be reconciled. Check which timestamp the report uses before counting a refund in a monthly total. An order created near a month end might settle after the next close. A separate pending category makes the finance result easier to interpret."
