          "The Shopify Collabs merchant payment guide describes processing through the Shopify bill and the need for creators to activate automatic payouts. It identifies a Waiting for creator state and warns that paying that commission outside Collabs could create a duplicate payment. Record estimated, held, billed, bill paid and receipt confirmation as separate states. If a creator reports that funds have not arrived, give finance the relevant bill and status and direct the creator to their official payout setup. Do not collect banking credentials in messages. In one hypothetical case, the merchant pays a monthly bill containing the commission, while the creator has yet to finish payout setup. The merchant can confirm the bill payment without asserting the recipient has received it. If the creator later activates payouts, keep the original status and append a dated observation. A separate production fee should be labeled and matched to its own contract. That prevents someone reading the records from assuming that a bank transfer settled the commission as well."
