          "Use the creator rates and usage rights guide to separate production, permission, publication and commission. Suppose the collaboration includes a 200-dollar production fee and commission on eligible orders. The fixed fee follows its own acceptance conditions. It does not belong in the commission hold. Record processing charges, conversion and other billing lines from the relevant statements. Review what the brand paid, what the creator can verify receiving and whether the records share a period. A customer’s final checkout total cannot establish the eligible sales base by itself. Discounts, returns and the program’s configured scope can matter. In a reconciliation workbook, give each payment type a separate reference and use a common currency only after documenting the conversion. Keep original currency and value for finance review. If a marketing team measures project cost, state which charges it includes. A sales report for the creator program may use a narrower denominator than a brand margin analysis. Both can be valid if the definitions are visible."
