          "The Shopify Collabs merchant payment guide describes commission disputes during the holding period. Verify the order, program, date, code and evidence before an authorized owner uses the applicable process. Unusual volume may justify review. It does not establish wrongdoing. Record the affected orders, submission time, response and decision. Append new evidence rather than overwriting the original observation. Keep the distinction between a dispute, a return and any decision to pause the relationship. For example, a discount code might appear on an unplanned page while orders still look ordinary in the storefront. Record where the code was actually observed and check the terms that apply. Do not assign responsibility for the publication without evidence. If a claim was mistaken, preserve the correction so finance does not hold an unrelated payment. Give the creator or representative the information they need to respond through the appropriate channel, while excluding other customers’ private details. Set a review date for the case."
