          "The Instagram Insights overview distinguishes views, accounts reached, interactions and follower trends. Use the definitions and dates available in the actual account. If a content-level follow metric is available, record its scope rather than attributing the entire account’s net change to one post. Keep profile visits, follows and unfollows separate. One account can see several posts. Adding their reach figures does not deduplicate people at account level. Use the Instagram follower change guide to distinguish additions, unfollows, net change and missing data. Check how your exports define the reporting period before comparing series. If native insights display views but not profile visits for a given item, leave visits unknown. Do not estimate them from likes. If you compare followers with the prior week, make sure the earlier value was taken under compatible settings. When promotion ran, label the affected records and inspect available paid reporting before describing the change as organic."
