          "The TikTok recommendation help describes the LIVE stream discovery surface. Before planning a broadcast, verify the account’s actual ability to host and use needed features. Assign host, moderation, product review, connectivity fallback and recap ownership. Use demonstrations that can be shown under the actual conditions. Where a motion needs a controlled setup, use an appropriate approved recording or explanation. Decide how to route questions you cannot answer on air. Use the creator live campaign runbook to plan a rehearsal. Keep concurrent observations, later replay and campaign actions under their own reporting definitions. Suppose a viewer asks whether a stand is approved for a different product. The host can say which model is being shown and direct the person to official compatibility information. The team should have approved language for questions about use outside the test. A short live discussion with a defined purpose may be a better pilot than a long broadcast with no follow-up owner."
