          "The Social Cat invitations guide describes receiving an invitation and moving into a matched or active workflow after acceptance. Open the actual offer and verify brand, assignment, contact, expiry and collaboration type. If email and platform messages differ, confirm the request through the original record or a verifiable brand route. A direct message alone does not establish payment. Ask specific questions while details are unclear. An urgent reply request does not resolve missing terms. Keep the message date and confirmed contact without collecting unrelated identity information. Suppose a brand profile names a retail product but the person contacting you refers to a different company. Check whether they are an authorized representative and which entity will supply the sample or pay for work. A legitimate company can work through an agency. You still need to know who makes and can approve the actual offer. Avoid opening an unknown attachment to prove the connection. The goal is a reliable project record that both parties can recognize later."
