          "The Social Cat collaboration types guide distinguishes gifting, paid and affiliate work and describes direct brand-to-creator handling of paid or affiliate compensation. Ask whether a product is gifted, loaned or expected back, and who bears applicable shipping charges. A fixed fee needs amount, currency, payment trigger and date. Commission needs eligible orders, returns, reporting, review date and payer. If an offer has all three, keep separate lines. Use the creator rates and usage rights guide to account for scripting, production, revisions, posting and permissions. Suppose a product has a stated retail value of 60 dollars and the request includes two videos plus revisions. Retail value is not available cash for your expenses. Estimate the time and costs you would actually incur. If the brand offers a share of future sales, leave the payout uncertain unless supported orders exist. Ask how you can verify the results that affect you. A clear offer lets both sides distinguish a sample that arrived from compensation that remains due."
