          "Use the creator rates and usage rights guide to document rider appearance, creator publication, brand use, advertising, derivatives, territory and duration. Check location, the relevant permission for filming the horse and any other people through the appropriate owners. If using event footage, review organizer and production rights separately. The FTC influencer disclosure guidance addresses commercial endorsements with a material connection for a U.S. audience. Check the actual market and relationship. Before export, review the footage and copy so venue approval is not described as an institutional endorsement. A rider can allow an interview on one channel while the event footage remains subject to separate permissions. Give the publisher a rights record that names the actual asset. If a promotional use was omitted from the original agreement, request a new review before adapting it. Include expiry and a responsible person for removal or renewal. Keep approval evidence with the released version so a later edit does not inherit an unrelated permission."
