        [
          "Upfluence 商店集成功能表描述 Shopify 的折扣码、联盟链接和销售跟踪，也说明实现会因集成而异。创建测试矩阵，用不同订单检查只用码、只经链接、同时出现、没有两者。若平台的链接自动应用某码，记录它实际发生，不把链接测试假装成独立于码。每条保留设备、时间、所选商品、订单 ID 和两个系统看到的状态。未知规则向厂商问实际条件。",
          "The Upfluence integration capability guide describes Shopify discount codes, affiliate links and sales tracking, and distinguishes implementations by integration. Build a matrix with separate test orders for code, link, both and neither. If the configured link applies a code automatically, record the observed behavior rather than treating that route as independent of code. Retain device, time, product, order ID and the state seen in each system. Ask the vendor about unresolved conditions in the proposed setup. Include a code with a permitted product and one with an excluded item if that distinction matters. Verify what the checkout actually applies and what the reporting later attributes. In an appropriate test environment, note whether the platform accepts test events and how they are labeled. If a test order never enters the vendor export, do not declare the link broken until you know whether such orders are collected. Use a documented test path or record that the behavior remains unknown."
        ],
        [
          "upCMS"
        ]
