          "The Shopify order refund guide describes full and partial refunds in Shopify. It does not establish when or how Upfluence changes a commission. Use approved test cases for a full refund, a partial refund and an adjustment after a reporting cutoff. Compare Shopify, vendor and finance records. Suppose an eligible base of 120 dollars has a 30-dollar refund. Record the adjustment. If the agreement uses ten percent of the remaining eligible ninety dollars, the expected commission under that rule is nine dollars. Then verify whether the software uses the same rule. Treat the numbers as a worked example. If shipping or a product outside the program was refunded, check whether it affects the eligible base. Preserve initial and revised values and review dates. The finance owner can decide whether to close the period with a pending adjustment or carry the change into a later report. Ask the vendor to clarify timing when two permitted records disagree."
