          "Give an export to a second reviewer and ask them to recover order, creator, link or code, charges, currency, refund and status. If an identifier is missing, document the additional evidence and manual work needed. Use the creator rates and usage rights guide to distinguish commission, production fee and ad permission. A vendor performance row cannot substitute for a verified payment receipt. If another service handles settlement, record the source and owner. Confirm that the export can explain a refund before scaling use. A finance acceptance test might require reproducing three orders and one adjustment from original records. Ask the reviewer to identify which value comes from Shopify and which comes from the vendor. Verify that the export does not include information the receiving team cannot use. If the analyst needs a new report after a correction, preserve the old export and the reason for replacement. A revised number should be traceable to an order or an approved decision."
