          "YouTube 独立观众帮助说明该指标是一定时间内实际观看观众数的估算，重复观看会按估算口径去重。它也说明 Shorts 的处理与相关观看口径。对两条视频的独立观众分别保存，不能把两条相加当频道的独立人数。检查账号、日期范围、选了哪些视频、是否包括 Shorts 和直播。若有权限可请持有人拿对应报告，没数据就写缺失。",
          "The YouTube unique viewers help describes an estimate of distinct viewers who watched in a specified period. Repeated viewing is accounted for within the metric’s scope. It also explains how Shorts use engaged views in the estimate. Keep video-level observations separate. The same person can watch two videos, so adding their unique viewer figures does not give a deduplicated channel total. Record account, date range, included videos and whether Shorts or LIVE content are in scope. Ask the authorized channel owner for the report if needed. Leave the value unavailable if it cannot be obtained. A public view count may still give context about the visible asset. It cannot stand in for the estimated number of distinct people who watched. If someone compares a thirty-day native estimate with a video’s lifetime public count, note that both the unit and window differ. For a sponsorship, decide in advance which period is appropriate and use the same elapsed period for comparables."
