          "YouTube 受众分析帮助将月度受众定义为过去 28 天观看内容的独立观众估算，并介绍新观众、偶尔观众与常看观众。该帮助还介绍订阅与未订阅者的观看时长比例。比例描述的是时间，不是订阅者人数或所有订阅者都看了多少。若要看活动期间，记具体日期并核对所选指标是否仍用滚动 28 天。不要把它写成自然月。",
          "The YouTube Audience analytics help describes monthly audience as estimated unique viewers over the preceding twenty-eight days. It also describes new, casual and regular viewers and the watch-time split between subscribers and viewers who are not subscribed. A watch-time percentage is a share of time. It does not establish the number of subscribers who watched or how much each person watched. For a campaign, record the actual date and check whether the selected field still uses a rolling twenty-eight-day window. Do not label it a calendar month. Suppose a report shows a larger share of watch time from subscribers this month. That share can change because either group’s watch time changed. If only the percentage is available, do not claim which group caused the change. A cohort of regular viewers can help someone plan a follow-up series, while subscriber growth needs its own record. The reporting owner should preserve the original metric labels and the relevant screenshot or export date."
