          "Suppose a channel displays 125K public subscribers, an authorized monthly audience report estimates 38,000 and a tutorial has 7,500 estimated unique viewers for its selected period. Report the public size label, the recent channel audience estimate and the video estimate separately. Dividing 7,500 by 125K does not produce the share of subscribers who watched. The video can include people who never subscribed, and the public count is abbreviated. Use the YouTube sponsored content analytics guide to select comparable videos and fixed reporting windows. If one tutorial ran as an ad and another did not, identify what each report actually includes. A median of matched video results can be a description of your sample, provided you state its dates and coverage. It cannot guarantee the next upload will have the same audience. The brand can use this sample to decide which evidence to request. It should not use the arithmetic to claim that most subscribers ignored a video without a compatible report."
