          "Choose one or two comparable pieces per candidate. Record link, date, role and timecodes. At eight seconds you might see the hand and bolt, and at twelve seconds see it enter the catch. Check phone-size visibility, obstruction, continuity, useful audio and captions. The editorial photo shows the hand and component together. A real test should preserve that view through the action. A finished result alone does not show how the creator filmed the full procedure. The W3C captions guide describes captions for speech and meaningful sounds. Put the relevant caption needs in the brief. A latch click might help explain the endpoint when the viewer can also see it. If the draft uses text to identify the sound, verify that it is accurate and does not cover the part. For an entirely visual demonstration, give the buyer a way to inspect the key movement with sound off. Ask another reviewer to confirm the same timecodes."
