          "The TikTok recommendation help describes recommendation across surfaces such as For You, Following, search and LIVE. Comparable work can have different distribution contexts. When publication matters, review related topics, format and dates. Document any known advertising or collaboration. One high-view post cannot establish the outcome of a new project. Label public metric scope and leave unavailable fields unknown. If the deal requires a particular market, ask the authorized account owner for the applicable evidence instead of inferring it. A creator may have a large following for entertainment and a smaller sample of product tutorials. The second set may be more relevant to a brand instruction film. Consider whether a short demonstration should be evaluated by view counts or by how clearly it answers a question. A later account report may help explain distribution. It cannot replace a review of whether the right product and steps were shown. Record the information separately so a buyer can see which requirement each source supports."
